import { Mesh, PlaneGeometry, Float32BufferAttribute, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as texNode } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // --- Load texture (synchronous via ctx.textureLoader) ---
  const tex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // --- Determine atlas region ---
  // Expected format: config.atlas?.sourceRect = [x, y, width, height]
  const rect = (config.atlas && config.atlas.sourceRect) ? config.atlas.sourceRect : [0, 0, 512, 320];
  const [rx, ry, rw, rh] = rect;

  // Compute aspect ratio based on atlas region
  const aspect = rw / rh;

  // --- Create plane geometry matching aspect ratio ---
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Adjust UVs to map only the atlas region ---
  // Assuming the texture has already been loaded and its image dimensions are available
  const img = tex.image;
  const texW = img?.width ?? 1;
  const texH = img?.height ?? 1;

  const u0 = rx / texW;
  const v0 = ry / texH;
  const u1 = (rx + rw) / texW;
  const v1 = (ry + rh) / texH;

  // PlaneGeometry default UVs order: (0,0), (1,0), (0,1), (1,1)
  const uvs = new Float32Array([
    u0, v1,
    u1, v1,
    u0, v0,
    u1, v0,
  ]);
  geometry.setAttribute('uv', new Float32BufferAttribute(uvs, 2));

  // --- Create node‑based material ---
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  material.colorNode = texNode(tex);

  // --- Assemble mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.name = config.name ?? 'hero-showpiece';

  // Apply placement transforms (position, rotation, scale)
  if (config.position) mesh.position.set(...config.position);
  if (config.rotation) mesh.rotation.set(...config.rotation);
  if (config.scale) mesh.scale.set(...config.scale);

  // --- Billboard behavior (always faces camera) ---
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // --- Event handlers container (empty for this node) ---
  mesh.userData.handlers = {};

  // --- Cleanup routine ---
  mesh.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Kill any GSAP timelines that might have been attached (none for this node)
    gsap.globalTimeline.kill();

    // Remove reference to texture if it was uniquely created for this node
    // (Usually managed by ctx.textureLoader cache, so we do not dispose it here)
  };

  // No cinematic primitives to apply per specification
  // If future primitives are added, they can be invoked here:
  // (config.cinematicPrimitives || []).forEach(p => {
  //   if (ctx.primitives[p.name]) ctx.primitives[p.name](mesh, p.params);
  // });

  return mesh;
}
